use crate::lucide_icons;
use plico::SvgAsset;

/// Compatibility names used by the application UI. The SVG bytes themselves
/// are selected and generated by `plico icons`; do not hand-maintain assets.
pub fn get(name: &str) -> &'static SvgAsset {
    match name {
        "grid" => &lucide_icons::LAYOUT_GRID,
        "star" => &lucide_icons::STAR,
        "key" => &lucide_icons::KEY_ROUND,
        "card" => &lucide_icons::CREDIT_CARD,
        "person" => &lucide_icons::USER,
        "note" => &lucide_icons::STICKY_NOTE,
        "terminal" => &lucide_icons::TERMINAL,
        "folder" => &lucide_icons::FOLDER,
        "shield" => &lucide_icons::SHIELD,
        "clock" => &lucide_icons::CLOCK,
        "sliders" => &lucide_icons::SLIDERS_HORIZONTAL,
        "search" => &lucide_icons::SEARCH,
        "sort" => &lucide_icons::ARROW_UP_DOWN,
        "eye" => &lucide_icons::EYE,
        "copy" => &lucide_icons::COPY,
        "external" => &lucide_icons::EXTERNAL_LINK,
        "globe" => &lucide_icons::GLOBE,
        "lock" => &lucide_icons::LOCK,
        "plus" => &lucide_icons::PLUS,
        "sidebar" => &lucide_icons::PANEL_LEFT,
        "chevron" => &lucide_icons::CHEVRON_RIGHT,
        "chevron-down" => &lucide_icons::CHEVRON_DOWN,
        "bell" => &lucide_icons::BELL,
        "alert" => &lucide_icons::TRIANGLE_ALERT,
        "back" => &lucide_icons::ARROW_LEFT,
        "check" => &lucide_icons::CHECK,
        "settings" => &lucide_icons::SETTINGS,
        "sync" => &lucide_icons::REFRESH_CW,
        "edit" => &lucide_icons::PENCIL,
        "trash" => &lucide_icons::TRASH,
        "archive" => &lucide_icons::ARCHIVE,
        "restore" => &lucide_icons::ARCHIVE_RESTORE,
        "save" => &lucide_icons::SAVE,
        "mail" => &lucide_icons::MAIL,
        "arrow-left" => &lucide_icons::ARROW_LEFT,
        "arrow-right" => &lucide_icons::ARROW_RIGHT,
        "login" => &lucide_icons::LOG_IN,
        "close" => &lucide_icons::X,
        "eye-off" => &lucide_icons::EYE_OFF,
        "power" => &lucide_icons::POWER,
        "minus" => &lucide_icons::MINUS,
        "expand" => &lucide_icons::MAXIMIZE_2,
        other => panic!("unknown application icon: {other}"),
    }
}
